import re
from collections import deque

def tokenize(expr):
    """Tokenize the expression into NUMBER, LPAREN, RPAREN, and OP tokens."""
    tokens = []
    i = 0
    expr = expr.replace(' ', '')  # Remove whitespace

    while i < len(expr):
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('NUMBER', int(expr[i:j])))
            i = j
        elif expr[i] == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif expr[i] == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        elif expr[i] in '+-*/':
            tokens.append(('OP', expr[i]))
            i += 1
        else:
            raise ValueError(f"Invalid character in expression: {expr[i]}")
    return tokens

def parse_add_sub(tokens, pos):
    """Parse addition and subtraction (lowest precedence)."""
    if pos[0] >= len(tokens) or tokens[pos[0]][0] != 'NUMBER':
        left = parse_mul_div(tokens, pos)[1]

    while pos[0] < len(tokens) and tokens[pos[0]] in ('+', '-'):
        op = tokens[pos[0]][1]
        pos[0] += 1
        right = parse_mul_div(tokens, pos)[1]
        left = left if op == '+' else left - right

    return left, pos

def parse_mul_div(tokens, pos):
    """Parse multiplication and division (medium precedence)."""
    if pos[0] >= len(tokens) or tokens[pos[0]][0] != 'NUMBER':
        left = parse_primary(tokens, pos)[1]
    else:
        left = tokens[pos[0]][1]
        pos[0] += 1

    while pos[0] < len(tokens) and tokens[pos[0]] in ('*', '/'):
        op = tokens[pos[0]][1]
        pos[0] += 1
        if tokens[pos[0]][0] != 'NUMBER':
            raise ValueError("Expected number after operator")
        right = tokens[pos[0]][1]
        pos[0] += 1

        if op == '/' and right == 0:
            raise ZeroDivisionError("division by zero")
        left = left * right if op == '*' else left // right

    return left, pos

def parse_primary(tokens, pos):
    """Parse primary expression: numbers, parentheses, unary minus."""
    if pos[0] >= len(tokens):
        return 0, pos

    if tokens[pos[0]][0] == 'NUMBER':
        value = tokens[pos[0]][1]
        pos[0] += 1
        return value, pos

    elif tokens[pos[0]] == 'LPAREN':
        pos[0] += 1  # consume '('
        value, pos[0] = parse_add_sub(tokens, pos)
        if pos[0] >= len(tokens) or tokens[pos[0]][0] != 'RPAREN':
            raise ValueError("Expected ')' to close parenthesis")
        pos[0] += 1  # consume ')'
        return value, pos

    elif tokens[pos[0]] == '-':
        pos[0] += 1  # consume '-'
        value, pos = parse_primary(tokens, pos)
        return -value, pos

    else:
        raise ValueError(f"Unexpected token: {tokens[pos[0]]}")

def eval_expression(expr):
    """Evaluate a mathematical expression string. Supports +, -, *, / with correct precedence."""
    if not expr.strip():
        raise ValueError("Empty expression")

    tokens = tokenize(expr)
    pos = [0]  # mutable index for passing around in recursive calls
    result, _ = parse_add_sub(tokens, pos)

    if pos[0] < len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos[0]]} at end of expression")

    return result
